'use strict';
var fs=require('fs'),path=require('path'),os=require('os'),crypto=require('crypto'),cp=require('child_process'),util=require('util'),setup=require('./setup'),io=require('./io');
function Bootstrap(deps){this.d=deps;this.closed=false;this.session=null;this.uid=null;this.probe=null;this.busy=null;}
Bootstrap.prototype.tick=function(){var self=this;if(this.closed)return Promise.resolve();if(this.busy)return this.busy;this.busy=this.step().then(function(v){self.busy=null;return v;},function(e){self.busy=null;throw e;});return this.busy;};
Bootstrap.prototype.step=async function(){var d=this.d,app=d.findApp();if(this.session&&(!app||app.uid!==this.uid)){var previous=this.session;this.session=null;this.uid=null;await previous.stop();}if(this.closed)return;if(!app){await d.publish(null,'Waiting for BimmerVision app');return;}if(this.session&&app.uid===this.uid)return;d.platform();await d.prepare(app);await d.publish(app,'Preparing recorder');var tls=await d.ensureTLS();if(this.closed)return;
 var hardware=d.readHardware(),valid=hardware&&hardware.hardwareTest===true&&hardware.adapterVerified===true&&hardware.receiverSha256===d.receiverHash;
 if(!valid){hardware=d.legacyEnrollment(app);valid=!!hardware;}
 if(!valid){await d.retireLegacy();await d.publish(app,'Checking camera streams');var probe=d.probe();this.probe=probe;var result;try{result=await probe;}finally{this.probe=null;}if(this.closed)return;var current=d.findApp();if(!current||current.uid!==app.uid)return;hardware={hardwareTest:true,adapterVerified:true,receiverSha256:d.receiverHash,streams:result.streams,verifiedAt:new Date().toISOString()};}
 if(this.closed)return;var actual=d.findApp();if(!actual||actual.uid!==app.uid)return;hardware.uid=app.uid;await d.saveHardware(hardware);await d.retireLegacy();if(this.closed)return;var session=await d.start(app,tls);if(this.closed){await session.stop();return;}this.session=session;this.uid=app.uid;await d.publish(app,'Ready',true);};
Bootstrap.prototype.stop=async function(){if(this.closed)return;this.closed=true;if(this.probe&&this.probe.cancel)this.probe.cancel();if(this.busy)try{await this.busy;}catch(ignore){}if(this.session){var s=this.session;this.session=null;await s.stop();}};
function readLegacy(app,hash,base){base=base||'/var/opt/bimmervision-service';try{var current=fs.realpathSync(path.join(base,'current')),allowed=path.resolve(base)+path.sep;if(current.indexOf(allowed)!==0)return null;var conf=setup.json(path.join(current,'hardware.json'));if(!conf||conf.uid!==app.uid||conf.hardwareTest!==true||conf.adapterVerified!==true||setup.digest(path.join(current,'receiver'))!==hash)return null;var st=setup.safe(path.join(current,'hardware.json'));if(st.uid!==0||(st.mode&63)!==0)return null;conf.receiverSha256=hash;conf.migratedFrom='local verified recorder';return conf;}catch(e){return null;}}
async function retireLegacy(base,run){base=base||'/var/opt/bimmervision-service';run=run||util.promisify(cp.execFile);var unit='/etc/systemd/system/bimmervision-service.service',st=setup.safe(unit,true);if(!st)return false;if(!st.isFile()||st.uid!==0)throw Error('Legacy recorder unit ownership changed');var text=fs.readFileSync(unit,'utf8');if(!/^ExecStart=\/usr\/bin\/node \/var\/opt\/bimmervision-service\/current\/main\.js\s*$/m.test(text))throw Error('Legacy recorder service is not owned by BimmerVision');await run('/bin/systemctl',['stop','bimmervision-service.service'],{timeout:30000,maxBuffer:65536});var ro=fs.readFileSync('/proc/mounts','utf8').split('\n').some(function(l){var a=l.split(' ');return a[1]==='/'&&a[3].split(',').indexOf('ro')>=0;});try{if(ro)await run('/bin/mount',['-o','remount,rw','/'],{timeout:10000});await run('/bin/systemctl',['disable','bimmervision-service.service'],{timeout:10000,maxBuffer:65536});}finally{if(ro)await run('/bin/mount',['-o','remount,ro','/'],{timeout:10000});}return true;}
function realDependencies(options){var o=options||{},root=o.root||__dirname,base=o.base||path.dirname(fs.realpathSync(root)),data=o.data||'/var/opt/bimmervision-recorder/data',marker=o.marker||'/var/opt/bimmervision-recorder/setup-status.json',main=require('./main'),hash=setup.json(path.join(root,'RECEIVER-PROVENANCE.json')).sha256,binary=path.join(root,'receiver');var boot=fs.readFileSync('/proc/sys/kernel/random/boot_id','utf8').trim(),version=require('./version.json').version;
 return {findApp:function(){return setup.findApp(o);},platform:function(){setup.platform(o);},receiverHash:hash,prepare:async function(app){setup.privateDir(data);await main.prepareControls('/tmp/bimmervision-'+app.uid,app.uid);},ensureTLS:function(){return setup.ensureTLS(data);},readHardware:function(){var p=path.join(data,'hardware.json'),v=setup.json(p,true);if(v){var st=setup.safe(p);if(st.uid!==0||(st.mode&63)!==0)throw Error('Recorder enrollment has unsafe permissions');}return v;},saveHardware:async function(v){await io.atomicJSON(path.join(data,'hardware.json'),v);},legacyEnrollment:function(app){return readLegacy(app,hash);},retireLegacy:function(){return retireLegacy();},probe:function(){return setup.probeReceiver(binary,{sha256:hash});},start:function(app,tls){return main.start({root:root,configFile:path.join(data,'hardware.json'),tlsKey:tls.key,tlsCert:tls.cert});},publish:async function(app,state,ready){await io.atomicJSON(marker,{version:version,state:state,phase:ready?'ready':'preparing',bootId:boot,uid:app?app.uid:null});await io.chmod(marker,420);if(app&&!ready){var c=new main.Controls('/tmp/bimmervision-'+app.uid,app.uid);await c.write({apiVersion:1,state:state,error:null,drives:[],drive:null,recordingCount:0,writeInProgress:false,safeToRemove:true,activeId:null,setupPending:true});}}};}
async function run(options){process.umask(63);var deps=realDependencies(options),manager=new Bootstrap(deps),timer=null,stopped=false;async function loop(){if(stopped)return;try{await manager.tick();}catch(e){try{var app=deps.findApp();await deps.publish(app,/camera|stream/i.test(e.message)?'Waiting for supported camera streams':'Recorder setup pending');}catch(ignore){}console.error('BimmerVision setup: '+String(e.message).slice(0,300));}if(!stopped)timer=setTimeout(loop,manager.session?1000:10000);}function stop(){if(stopped)return;stopped=true;clearTimeout(timer);manager.stop().then(function(){process.exit(0);},function(){process.exit(1);});}process.on('SIGTERM',stop);process.on('SIGINT',stop);await loop();return manager;}
module.exports={Bootstrap:Bootstrap,realDependencies:realDependencies,readLegacy:readLegacy,retireLegacy:retireLegacy,run:run};
if(require.main===module)run().catch(function(e){console.error('BimmerVision setup: '+e.message);process.exitCode=1;});
